<template>
  <section class="admin-page">
    <div class="header-row"><div><p class="eyebrow">Access control</p><h1>User & role management</h1><p>Manage participant and organizer access without exposing privileged admin controls.</p></div><button class="primary" @click="openCreate">+ New user</button></div>
    <div class="toolbar"><div class="filters"><select v-model="roleFilter"><option value="">All roles</option><option value="participant">Participant</option><option value="organizer">Organizer</option><option v-if="authStore.userRole === 'admin'" value="admin">Admin</option></select><select v-model="statusFilter"><option value="">All statuses</option><option value="active">Active</option><option value="inactive">Inactive</option><option value="suspended">Suspended</option></select></div><span>{{ meta.total ?? users.length }} users</span></div>
    <p v-if="feedback" class="notice" :class="tone">{{ feedback }}</p>
    <div class="table-shell"><table><thead><tr><th>User</th><th>Role</th><th>Status</th><th>Verification</th><th>Created</th><th class="right">Actions</th></tr></thead><tbody><tr v-if="loading"><td colspan="6" class="empty">Loading users...</td></tr><tr v-else-if="!users.length"><td colspan="6" class="empty">No users found.</td></tr><tr v-for="user in users" v-else :key="user.id"><td><strong>{{ user.full_name || 'Unnamed user' }}</strong><small>{{ user.email }}</small></td><td><span class="pill role">{{ user.role }}</span></td><td><span class="pill" :class="user.status">{{ user.status }}</span></td><td>{{ user.is_email_verified ? 'Verified' : 'Unverified' }}</td><td>{{ formatDate(user.created_at) }}</td><td class="right"><button class="table-action" :disabled="authStore.userRole !== 'admin' && user.role === 'admin'" @click="openEdit(user)">{{ authStore.userRole !== 'admin' && user.role === 'admin' ? 'Protected' : 'Edit' }}</button></td></tr></tbody></table></div>
    <div class="pager"><button :disabled="page <= 1" @click="page--">Previous</button><span>Page {{ page }} of {{ meta.pages || 1 }}</span><button :disabled="page >= (meta.pages || 1)" @click="page++">Next</button></div>

    <Teleport to="body"><div v-if="modalOpen" class="backdrop" @click.self="close"><form class="modal" @submit.prevent="save"><div class="modal-head"><div><p class="eyebrow">Account editor</p><h2>{{ editingId ? 'Update user' : 'Create user' }}</h2></div><button type="button" @click="close">×</button></div><div class="modal-body">
      <label v-if="!editingId" class="field"><span>Email</span><input v-model.trim="form.email" type="email" required /></label><label v-if="!editingId" class="field"><span>Temporary password</span><input v-model="form.password" type="password" minlength="8" maxlength="128" required /></label>
      <label class="field"><span>Full name</span><input v-model.trim="form.full_name" /></label><div class="grid"><label class="field"><span>Phone</span><input v-model.trim="form.phone" /></label><label class="field"><span>Country</span><input v-model.trim="form.country" /></label></div>
      <div class="grid"><label class="field"><span>Role</span><select v-model="form.role" :disabled="editingSelf"><option value="participant">Participant</option><option value="organizer">Organizer</option><option v-if="authStore.userRole === 'admin'" value="admin">Admin</option></select><small v-if="editingSelf">You cannot change your own role.</small></label><label class="field"><span>Status</span><select v-model="form.status" :disabled="editingSelf"><option value="active">Active</option><option value="inactive">Inactive</option><option value="suspended">Suspended</option></select><small v-if="editingSelf">You cannot disable your own account.</small></label></div>
      <label class="check"><input v-model="form.is_email_verified" type="checkbox" /> Email verified</label>
    </div><div class="modal-foot"><button type="button" class="secondary" @click="close">Cancel</button><button class="primary" :disabled="saving">{{ saving ? 'Saving...' : 'Save user' }}</button></div></form></div></Teleport>
  </section>
</template>

<script setup lang="ts">
import { useAdminOperations, type AdminUserCreatePayload, type AdminUserItem } from '~/composables/useAdminOperations';
definePageMeta({middleware:['auth','admin']});useSeoMeta({title:'Manage Users | IWBIF 2026'});const authStore=useAuthStore();const api=useAdminOperations();
const users=ref<AdminUserItem[]>([]),loading=ref(false),saving=ref(false),modalOpen=ref(false),editingId=ref(''),feedback=ref(''),tone=ref<'success'|'error'>('success');const page=ref(1),roleFilter=ref(''),statusFilter=ref('');const meta=reactive({total:0,pages:1});
const empty=():AdminUserCreatePayload=>({email:'',password:'',full_name:'',phone:'',country:'',role:'participant',status:'active',is_email_verified:false});const form=reactive(empty());const errorText=(error:unknown)=>{const value=error as {data?:{message?:string;errors?:Array<{message:string}>}};return value.data?.errors?.[0]?.message||value.data?.message||(error instanceof Error?error.message:'User could not be saved.');};
const editingSelf=computed(()=>Boolean(editingId.value&&editingId.value===authStore.user?.id));
const load=async()=>{loading.value=true;try{const result=await api.getUsers(page.value,20,roleFilter.value,statusFilter.value);users.value=result.data||[];meta.total=result.meta?.total||users.value.length;meta.pages=result.meta?.pages||1;}catch(error){tone.value='error';feedback.value=errorText(error);}finally{loading.value=false;}};const openCreate=()=>{editingId.value='';Object.assign(form,empty());modalOpen.value=true;};const openEdit=(user:AdminUserItem)=>{editingId.value=user.id;Object.assign(form,{...empty(),full_name:user.full_name||'',phone:user.phone||'',country:user.country||'',role:user.role,status:user.status,is_email_verified:Boolean(user.is_email_verified)});modalOpen.value=true;};const close=()=>{modalOpen.value=false;editingId.value='';};
const save=async()=>{if(saving.value)return;saving.value=true;try{if(editingId.value)await api.updateUser(editingId.value,{full_name:form.full_name||null,phone:form.phone||null,country:form.country||null,role:form.role,status:form.status,is_email_verified:form.is_email_verified});else await api.createUser({...form,full_name:form.full_name||null,phone:form.phone||null,country:form.country||null});tone.value='success';feedback.value=editingId.value?'User updated.':'User created.';close();await load();}catch(error){tone.value='error';feedback.value=errorText(error);}finally{saving.value=false;}};watch(page,load);watch([roleFilter,statusFilter],async()=>{if(page.value!==1)page.value=1;else await load();});await load();const formatDate=(value?:string)=>value?new Intl.DateTimeFormat('en-GB',{dateStyle:'medium'}).format(new Date(value)):'—';
</script>

<style scoped>
.admin-page{max-width:80rem;margin:auto;padding:2.5rem .75rem}.header-row{display:flex;flex-wrap:wrap;align-items:end;justify-content:space-between;gap:1.25rem}.eyebrow{font-size:.75rem;text-transform:uppercase;letter-spacing:.3em;color:#a5f3fc}.header-row h1{margin-top:.75rem;font-size:2.25rem;font-weight:900}.header-row p:not(.eyebrow){margin-top:.75rem;color:#94a3b8}.toolbar{margin-top:2rem;display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:1rem;border:1px solid #ffffff1a;border-radius:1.5rem;background:#ffffff08;padding:1rem;color:#94a3b8;font-size:.875rem}.filters{display:flex;flex-wrap:wrap;gap:.75rem}.filters select,.field input,.field select{border:1px solid #ffffff1a;border-radius:1rem;background:#020617cc;padding:.75rem 1rem;color:white}.notice{margin-top:1.25rem;border:1px solid;padding:1rem;border-radius:1rem}.notice.success{border-color:#6ee7b74d;background:#064e3b4d}.notice.error{border-color:#fca5a54d;background:#7f1d1d4d}.table-shell{margin-top:1.5rem;overflow-x:auto;border:1px solid #ffffff1a;border-radius:2rem;background:#02061773}table{width:100%;min-width:850px;text-align:left}th{background:#ffffff0a;padding:1rem 1.25rem;font-size:.68rem;text-transform:uppercase;letter-spacing:.18em;color:#94a3b8}td{border-top:1px solid #ffffff12;padding:1rem 1.25rem;color:#cbd5e1;font-size:.875rem}td strong,td small{display:block}td strong{color:white}td small{margin-top:.25rem;color:#64748b}.right{text-align:right}.pill{display:inline-flex;border-radius:999px;padding:.35rem .7rem;font-size:.65rem;font-weight:800;text-transform:uppercase;letter-spacing:.1em}.pill.role{background:#22d3ee1f;color:#a5f3fc}.pill.active{background:#34d3991f;color:#a7f3d0}.pill.inactive,.pill.suspended{background:#f871711f;color:#fecaca}.table-action,.pager button,.secondary{border:1px solid #ffffff26;border-radius:999px;padding:.5rem 1rem;font-weight:700}.empty{text-align:center;padding:3rem}.pager{display:flex;justify-content:center;align-items:center;gap:1rem;margin-top:1.5rem;color:#94a3b8;font-size:.875rem}.pager button:disabled{opacity:.35}.primary{border-radius:999px;background:#67e8f9;padding:.75rem 1.25rem;font-weight:800;color:#083344}.backdrop{position:fixed;inset:0;z-index:100;display:flex;align-items:center;justify-content:center;padding:1rem;background:#020617cc;backdrop-filter:blur(12px)}.modal{width:min(100%,42rem);overflow:hidden;border:1px solid #ffffff21;border-radius:2rem;background:linear-gradient(145deg,#071a36,#020d20);box-shadow:0 35px 100px #0009}.modal-head,.modal-foot{display:flex;align-items:center;justify-content:space-between;gap:1rem;padding:1.25rem 1.75rem;border-bottom:1px solid #ffffff1a}.modal-head h2{margin-top:.5rem;font-size:1.5rem;font-weight:900}.modal-head button{font-size:1.75rem}.modal-body{display:grid;gap:1rem;padding:1.5rem 1.75rem}.modal-foot{justify-content:flex-end;border-top:1px solid #ffffff1a;border-bottom:0}.field span{display:block;margin-bottom:.5rem;font-size:.875rem;color:#cbd5e1}.field input,.field select{width:100%}.grid{display:grid;grid-template-columns:1fr 1fr;gap:1rem}.check{display:flex;gap:.75rem;color:#cbd5e1}@media(max-width:640px){.grid{grid-template-columns:1fr}.header-row h1{font-size:1.875rem}}
</style>
